window.TEST_PARTS=window.TEST_PARTS||{};window.TEST_PARTS["test6"]=(window.TEST_PARTS["test6"]||[]).concat([{"n":72,"page":29,"q":"Ո՞ր դեպքում կարող եք խաչմերուկն անցնել առանց ճանապարհը զիջելու՝ երթևեկության այլ մասնակցին։","options":["Ուղիղ անցնելու դեպքում","Աջ շրջադարձ կատարելիս","Ձախ շրջադարձ կատարելիս"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":73,"page":30,"q":"Աջ շրջադարձ կատարելիս պետք է","options":["Կանգ առնել «Կանգ-գծի» առջև՝ հետիոտններին չխոչընդոտելու նպատակով։","Մտնելով խաչմերուկ կանգ առնել՝ հետիոտններին չխոչընդոտելու նպատակով։","Անցնել խաչմերուկը՝ առանց կանգ առնելու։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":74,"page":30,"q":"Աջ շրջադարձ կատարելիս","options":["Պետք է զիջել ճանապարհը թեթև մարդատարի վարորդին։","Առաջինը անցնել խաչմերուկը։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":75,"page":30,"q":"Լուսացույցի թույլատրող ազդանշանի միանալուց հետո խաչմերուկ մուտք գործել կարող ենք","options":["Միայն հետադարձ կամ շրջադարձ կատարելու դեպքում։","Բոլոր դեպքերում։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":76,"page":31,"q":"Լուսացույցի կանաչ ազդանշանի միացման դեպքում պարտավոր ենք","options":["համոզվել, որ հետիոտնային անցման չերևացող մասում չկան անցումը չավարտած հետիոտներ:","լուսացույցի ազդանշանի համաձայն անմիջապես սկսել երթևեկությունը:"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":77,"page":31,"q":"Այս իրավիճակում հետադարձ կատարելիս ճանապարհը զիջել մյուս վարորդին","options":["Պարտավոր չենք։","Պարտավոր ենք։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":78,"page":31,"q":"Այս իրավիճակում ո՞ր ուղղությամբ կարող է վարորդը շարունակել երթևեկությունը։","options":["Միայն ուղիղ","Ուղիղ և աջ","Ուղիղ և ձախ","Բոլոր"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":79,"page":32,"q":"Ո՞ր վարորդը կարող է շարունակել երթևեկությունը։","options":["Ոչ ոք","Միայն ավտոբուսի վարորդը","Երկու վարորդներն էլ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":80,"page":32,"q":"Գծանցն անցնելը","options":["Թույլատրված է։","Արգելված է։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":81,"page":32,"q":"Վարորդին խաչմերուկն անցնել","options":["արգելվում է։","թույլատրվում է բոլոր դեպքերում։","թույլատրվում է, եթե նա հնարավորություն չունի առանց կտրուկ արգելակելու կանգնել «Կանգ-գծի» առջև:"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":82,"page":33,"q":"Լուսացույցի ազդանշանին ենթարկվելով՝ որտե՞ղ պետք է կանգնել։","options":["Լուսացույցի առջև","Հատվող երթևեկելի մասի առջև","Ցանկացած տեղում"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":83,"page":33,"q":"Ձախ շրջադարձ կատարելը թույլատրվում է","options":["Դարձափոխային գոտուց։","Նկարում նշված գոտուց։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":84,"page":33,"q":"Երթևեկությունը թույլատրվում է","options":["Միայն ուղիղ։","Միայն աջ։","Ուղիղ և աջ։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":85,"page":34,"q":"Երթևեկությունը թույլատրվում է","options":["Ուղիղ և աջ։","Միայն ուղիղ։","Միայն աջ։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":86,"page":34,"q":"Լուսացույցի կանաչ ազդանշանին պատկերված սլաքները տեղեկացնում են, որ","options":["Աջ շրջադարձն արգելված է։","Աջ ուղղությամբ երթևեկությունը կարգավորվում է լրացուցիչ սեկցիայով:"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":87,"page":34,"q":"Վազանցել բեռնատարին թույլատրվու՞մ է։","options":["Այո","Ոչ"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":88,"page":35,"q":"Ո՞ր ուղղությամբ վարորդը կարող է շարունակել երթևեկությունը այս իրավիճակում։","options":["Միայն ձախ","Պետք է սպասի թույլատրող ազդանշանի","Ձախ և հակառակ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":89,"page":35,"q":"Այս իրավիճակում մուտք գործել դարձափոխային երթևեկության գոտի","options":["Թույլատրվում է։","Թույլատրվում է միայն վազանց կատարելու նպատակով։","Արգելվում է։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":90,"page":35,"q":"Նշված գոտուց ուղիղ երթևեկությունը","options":["Թույլատրվում է։","Թույլատրվում է միայն հիմնական կանաչ ազդանշանի միանալուց հետո։","Արգելվում է։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":91,"page":36,"q":"Երթևեկությունը թույլատրվում է","options":["Ուղիղ և աջ։","Միայն աջ։","Բոլոր ուղղություններով։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":92,"page":36,"q":"Այս իրավիճակում երթևեկությունը","options":["Թույլատրվում է։","Արգելվում է։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":93,"page":36,"q":"Ավտոբուսի վարորդը երթևեկությունը սկսելուց կամ մանևր կատարելուց առաջ պետք է համոզված լինի, որ","options":["տվյալ պահին իր գոտում չկան այլ տրանսպորտային միջոցներ։","մանևրն անվտանգ է և խոչնդոտ չի ստեղծի երթևեկության մյուս մասնակիցների համար։","մանևրը կկատարի հնարավորինս արագ ճանապարհը շուտ ազատելու համար։"],"ans":2,"images_inline":[]},{"n":94,"page":36,"q":"Թույլատրվու՞մ է երթևեկել երթևեկելի մասի ձախ կողմում՝ նույն մակարդակի վրա գտնվող համընթաց ուղղությամբ տրամվայի գծերով, եթե տվյալ ուղղությամբ բոլոր գոտիները զբաղված են։","options":["Թույլատրվում է, եթե համապատասխան նշաններով երթևեկության այլ կարգ սահմանված չէ, և եթե դա խոչնդոտ չի ստեղծի տրամվայի երթևեկության համար","Թույլատրվում է միայն այն դեպքում, եթե տրանսպորտային միջոցն իրականացնում է վազանց","Արգելվում է բոլոր դեպքերում, քանի որ տրամվայի գծերը նախատեսված են բացառապես ռելսագնաց տրանսպորտային միջոցների համար"],"ans":1,"images_inline":[]},{"n":95,"page":37,"q":"Եթե երթևեկելի մասը գծանշմամբ բաժանված է գոտիների, ո՞ր դեպքում է վարորդին թույլատրվում հատել գոտիները բաժանող ընդհատվող գծերը։","options":["Թույլատրվում է հատել միայն վերադասավորում կատարելիս","Թույլատրվում է հատել և ընթանալ ընդհատվող գծի վրայով ցանկացած ժամանակ, եթե ճանապարհին այլ տրանսպորտային միջոցներ չկան","Երկու դեպքում էլ"],"ans":1,"images_inline":[]},{"n":96,"page":37,"q":"Ինչպիսի՞ տարածություն պետք է պահպանի ավտոբուսի վարորդն իր և առջևից ընթացող տրանսպորտային միջոցի միջև։","options":["Այնպիսի, որպեսզի հնարավորություն ունենա խուսափել դրա հետ բախվելուց։","Այնպիսի, որը թույլ կտա իրեն վազանցող այլ տրանսպորտային միջոցներին անարգել կատարել վազանց և վերադասավորվել իր առջև։"],"ans":1,"images_inline":[]},{"n":97,"page":37,"q":"Ինչպիսի՞ միջկողային տարածություն պետք է պահպանի ավտոբուսի վարորդն իր կողքով ընթացող տրանսպորտային միջոցից։","options":["Այնպիսի, որպեսզի հնարավորություն ունենա խուսափել դրա հետ բախվելուց։","0.5 մետրից ոչ պակաս տարածություն։","1 մետրից ոչ պակաս տարածություն։"],"ans":1,"images_inline":[]},{"n":98,"page":37,"q":"Բնակավայրից դուրս, յուրաքանչյուր ուղղության համար մեկ գոտի ունեցող երկկողմ երթևեկության ճանապարհներին 7 մետրից ավելի երկարություն ունեցող ավտոբուսների վարորդներն իրենց և առջևից ընթացող տրանսպորտային միջոցի միջև ի՞նչ տարածություն պետք է պահպանեն։","options":["Ոչ պակաս, քան 50 մետր տարածություն՝ անկախ երթևեկության արագությունից և ճանապարհային պայմաններից","Որպեսզի իրենց վազանցող տրանսպորտային միջոցների վարորդները հնարավորություն ունենան անհրաժեշտության դեպքում առանց խոչընդոտի վերադասավորվեն նախկինում զբաղեցրած գոտի","Իրենց հայեցողությամբ՝ ելնելով երթևեկության անվտանգությունից"],"ans":2,"images_inline":[]},{"n":99,"page":37,"q":"Վազանցը սկսելուց առաջ ավտոբուսի վարորդն ի թիվս այլ պահանջների, պետք է համոզված լինի, որ","options":["վազանցն ավարտելիս կարող է առանց վազանցվող տրանսպորտային միջոցի համար խոչընդոտ ստեղծելու վերադառնալ նախկինում զբաղեցրած գոտի։","առջևից ընթացող տրանսպորտային միջոցի վարորդը նկատել է իր մանևրը և արագությունը նվազեցնելու միջոցով զիջում է ճանապարհը։","երկու դեպքերում էլ։"],"ans":1,"images_inline":[]},{"n":100,"page":38,"q":"Վազանցը սկսելուց առաջ ավտոբուսի վարորդն ի թիվս այլ պահանջների, պետք է համոզված լինի, որ","options":["հետևից ընթացող տրանսպորտային միջոցները պահպանում են բավարար տարածություն, իսկ առջևի տրանսպորտային միջոցը արդեն սկսել է նվազեցնել արագությունը իրեն ճանապարհ տալու համար։","իր հետևից նույն գոտիով ընթացող տրանսպորտային միջոցը վազանց չի սկսել, իսկ առջևից ընթացողը վազանցի (ձախ շրջադարձի, հետադարձի) ազդանշան չի տվել։","Երկու դեպքերում էլ։"],"ans":2,"images_inline":[]},{"n":101,"page":38,"q":"Թույլատրվու՞մ է ոչ ռելսագնաց տրանսպորտային միջոցներին վազանցել աջ կողմից։","options":["Թույլատրվում է վազանցել աջ կողմից այն դեպքում, երբ առջևից ընթացող տրանսպորտային միջոցի վարորդը տվել է ձախ շրջադարձի ազդանշան և սկսել է մանևրի կատարումը","Արգելվում է բոլոր դեպքերում, քանի որ վազանցը պետք է կատարվի բացառապես ձախ կողմից՝ անվտանգության նկատառումներից ելնելով"],"ans":1,"images_inline":[]},{"n":102,"page":38,"q":"Այն դեպքերում, երբ բնակավայրերից դուրս մեծ եզրաչափեր ունեցող ավտոբուսին վազանց կատարելը դժվար է, ի՞նչ պետք է ձեռնարկի ավտոբուսի վարորդը։","options":["Պարտավոր է երթևեկել հնարավորինս աջ, իսկ անհրաժեշտության դեպքում կանգ առնի իր հետևից ընթացող տրանսպորտային միջոցներին բաց թողնելու համար։","Պարտավոր է միացնել վթարային լուսային ազդանշանը և շարունակել երթևեկությունը նույն արագությամբ` մինչև վազանցի համար թույլատրելի հատվածի հասնելը"],"ans":1,"images_inline":[]},{"n":103,"page":38,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին միաժամանակ վազանցել մի քանի տրանսպորտային միջոցների։","options":["Թույլատրվում է, եթե մանևրն անվտանգ կլինի երթևեկության մյուս մասնակիցների համար","Արգելվում է, վարորդը պարտավոր է յուրաքանչյուր տրանսպորտային միջոցին վազանցելուց հետո վերադառնալ իր նախկին գոտի և նոր միայն սկսել հաջորդ վազանցը","Թույլատրվում է միայն դանդաղընթաց տրանսպորտային միջոցներին"],"ans":1,"images_inline":[]},{"n":104,"page":38,"q":"Թույլատրվու՞մ է վազանց սկսել այն տրանսպորտային միջոցին, որի վարորդը տվել է ձախ շրջադարձի լուսային ազդանշան և սկսել է մանևրի կատարումը։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է միայն այն դեպքում, երբ դա կատարվում է աջ կողմից"],"ans":3,"images_inline":[]},{"n":105,"page":38,"q":"Արգելվու՞մ է հետադարձը ճանապարհի թեկուզ և մեկ ուղղությամբ 100մ-ից պակաս տեսանելիության տեղերում։","options":["Արգելվում է միայն բնակավայրերում","Արգելվում է բնակավայրերից դուրս","Արգելվում է բոլոր ճանապարհներին","Չի արգելվում"],"ans":3,"images_inline":[]},{"n":106,"page":39,"q":"Ի՞նչ պետք է ձեռնարկի ավտոբուսի վարորդը հետընթացով երթևեկելիս անվտանգությունն ապահովելու համար։","options":["Անընդհատ տա ձայնային ազդանշան","Պետք է միացնի գաբարիտային լույսերը և շարժվի հնարավորինս նվազագույն արագությամբ","Անհրաժեշտության դեպքում դիմի այլ անձանց օգնությանը","Կատարի թվարկված բոլոր գործողությունները"],"ans":3,"images_inline":[]},{"n":107,"page":39,"q":"Ինչպե՞ս պետք է վարորդը որոշի երթևեկելի գոտիների քանակը, եթե բացակայում են ճանապարհային գծանշումները և երթևեկության ուղղությունները սահմանող համապատասխան թելադրանքի նշանները։","options":["Եթե գծանշումները չկան, ապա ճանապարհը համարվում է մեկ գոտի ունեցող՝ անկախ դրա լայնությունից","Գոտիների քանակը որոշվում է ՝ հաշվի առնելով երթևեկելի մասի լայնությունը, տրանսպորտային միջոցների եզրաչափերը և դրանց միջև անհրաժեշտ միջկողային տարածությունը"],"ans":2,"images_inline":[]},{"n":108,"page":39,"q":"Միևնույն ուղղությամբ երեք և ավելի գոտիներ ունեցող ճանապարհներին ո՞ր դեպքում է թույլատրվում կանոնավոր փոխադրումները իրականացնող ավտոբուսներին զբաղեցնել ձախ եզրային գոտին ։","options":["Ինտենսիվ երթևեկության ժամանակ, եթե մյուս բոլոր գոտիները զբաղված են","Միայն այլ տրանսպորտային միջոցների վազանց կատարելու կամ արգելքը շրջանցելու նպատակով","Միայն ձախ շրջադարձ կամ հետադարձ կատարելու համար","Ցանկացած դեպքում"],"ans":3,"images_inline":[]},{"n":109,"page":39,"q":"Ավտոբուսի վարորդը տրանսպորտային միջոցի տեխնիկական պատճառներով չի կարող զարգացնել 40կմ/ժ-ից ավելի արագություն, թույլատրվու՞մ է արդյոք դուրս գալ զբաղեցրած աջ եզրային գոտուց՝ ձախ կողմում կանգառ կատարելու նպատակով։","options":["Արգելվում է, քանի որ 40կմ/ժ-ից ոչ ավելի արագությամբ ընթացող տրանսպորտային միջոցները պետք է երթևեկեն բացառապես աջ եզրային գոտիով՝ առանց դրանից դուրս գալու իրավունքի","Թույլատրվում է, եթե կանգառը կատարվում է այնպիսի վայրում, որտեղ դա թույլատրվում է կանոններով"],"ans":2,"images_inline":[]},{"n":110,"page":39,"q":"Բնակավայրում ինտենսիվ երթևեկության ժամանակ ո՞ր դեպքում է թույլատրվում փոխել երթևեկության գոտին։","options":["Միայն ձախ և աջ շրջադարձերի ժամանակ","Միայն հետադարձի ժամանակ","Միայն արգելքը շրջանցելուց և կանգառ կատարելուց առաջ","Թվարկված բոլոր դեպքերում։","Միայն 1 և 3 դեպքերում։"],"ans":4,"images_inline":[]},{"n":111,"page":40,"q":"Արգելվու՞մ է ավտոբուսների երթևեկությունը կողնակներով, մայթերով և հետիոտնային արահետներով՝ այլ հնարավորության բացակայության դեպքում։","options":["Արգելվում է","Թույլատրվում է ճանապարհային շահագործման և կոմունալ սպասարկման ծառայությունների ավտոբուսներին՝ խոչընդոտ չհանդիսանալով հետիոտներին և ապահովելով երթևեկության անվտանգությունը"],"ans":2,"images_inline":[]},{"n":112,"page":40,"q":"Բնակավայրից դուրս ո՞ր գոտիով պետք է երթևեկեն ավտոբուսները։","options":["Երթևեկելի մասի աջ եզրին հնարավորինս մոտ","Ցանկացած գոտիով, բացի ձախ եզրային գոտուց","Վարորդի հայեցողությամբ՝ ապահովելով երթևեկության անվտանգությունը"],"ans":1,"images_inline":[]},{"n":113,"page":40,"q":"Բնակավայրում <<Ճանապարհ ավտոմոբիլների համար>> նշանով կահավորված ճանապարհին ո՞ր գոտիով պետք է երթևեկեն ավտոբուսները։","options":["Երթևեկելի մասի աջ եզրին հնարավորինս մոտ։","Ցանկացած գոտիով, բացի ձախ եզրային գոտուց։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":114,"page":40,"q":"Միևնույն ուղղությամբ երեք գոտի ունեցող ճանապարհին ո՞ր գոտիներով է թույլատրվում երթևեկել ուղևորների կանոնավոր փոխադրում իրականացնող ավտոբուսներին։","options":["Միայն առաջին և երկրորդ գոտինելով","Ցանկացած գոտիով, եթե երթևեկությունն ինտենսիվ է և մյուս գոտիները զբաղված են"],"ans":1,"images_inline":[]},{"n":115,"page":41,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին առանց անհրաժեշտության երթևեկել ցածր արագությամբ։","options":["Թույլատրվում է, եթե վարորդը հոգնած է","Արգելվում է, եթե դրանով խոչընդոտ է ստեղծում այլ տրանսպորտային միջոցների երթևեկության համար","Թույլատրվում է միայն խաչմերուկներում երթևեկելիս կամ կարգավորողի ազդանշաններին հետևելիս"],"ans":2,"images_inline":[]},{"n":116,"page":41,"q":"Արագություն ընտրելիս ավտոբուսի վարորդին արգելվում է՝","options":["Գերազանցել տրանսպորտային միջոցի վրա տեղադրված <<Արագության սահմանափակում >> ճանաչման նշանով նախատեսված արագությունը։","Երթևեկել 60կմ/ժ-ից ցածր արագությամբ բոլոր այն ճանապարհներին, որտեղ տեղադրված չէ նվազագույն արագությունը սահմանափակող նշան։","երկու դեպքում էլ։"],"ans":1,"images_inline":[]},{"n":117,"page":41,"q":"Արագություն ընտրելիս ավտոբուսի վարորդին արգելվում է՝","options":["Փոխադրել ուղեբեռը տվյալ ճանապարհահատվածի համար սահմանված առավելագույն թույլատրելի արագությամբ, եթե բեռի փաստաթղթերում նշված չէ կոնկրետ արագության սահմանափակում","Գերազանցել տրանսպորտային միջոցի վրա տեղադրված <<Արագության սահմանափակում >> ճանաչման նշանով նախատեսված արագությունը","երկու դեպքում էլ։"],"ans":2,"images_inline":[]},{"n":118,"page":41,"q":"Երթևեկության ընթացքում ավտոբուսի վարորդին արգելվում է՝","options":["կտրուկ արգելակել, եթե դա անհրաժեշտ չէ ճանապարհատրանսպորտային պատահարը կանխելու համար։","կատարել արգելակում այն դեպքերում, երբ հետևից ընթացող տրանսպորտային միջոցը չի պահպանում անվտանգ տարածություն։","երկու դեպքում էլ։"],"ans":1,"images_inline":[]},{"n":119,"page":41,"q":"Բնակավայրում <<Առավելագույն արագության սահմանափակում>> նշանի կիրառման դեպքում ո՞րն է երթևեկության առավելագույն թույլատրելի արագությունը, որը կարող է սահմանվել իրավասու մարմինների կողմից։","options":["80կմ/ժ։","90կմ/ժ։","Ցանկացած արագություն, որն անվտանգ է տվյալ ճանապարհահատվածի համար"],"ans":1,"images_inline":[]},{"n":120,"page":42,"q":"Բնակավայրերից դուրս <<Առավելագույն արագության սահմանափակում>> նշանի կիրառման դեպքում ո՞րն է երթևեկության առավելագույն թույլատրելի արագությունը, որը կարող է սահմանվել իրավասու մարմիններ կողմից։","options":["100կմ/ժ","110կմ/ժ","Ցանկացած արագություն, որն անվտանգ է տվյալ ճանապարհահատվածի համար"],"ans":2,"images_inline":[]},{"n":121,"page":42,"q":"Բնակավայրերում <<Առավելագույն արագության սահմանափակում >> նշանի կիրառմամբ առավելագույն թույլատրելի արագությունը սահմանվել է 80կմ/ժ։ Ի՞նչ առավելագույն արագությամբ կարող են երթևեկել կահավորված թափքում մարդ փոխադրող ավտոմոբիլը և երեխաների կազմակերպված խմբեր փոխադրող ավտոմոբիլը։","options":["80կմ/ժ","50կմ/ժ","60կմ/ժ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":122,"page":42,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում երթևեկել ավտոբուսի վարորդին, երբ նա քարշակում է թեթև մարդատար ավտոմոբիլ։","options":["50կմ/ժ","60կմ/ժ","90կմ/ժ"],"ans":1,"images_inline":[]},{"n":123,"page":42,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում երթևեկել երեխաների կազմակերպված խմբեր փոխադրող ավտոբուսին բնակավայրերում։","options":["50կմ/ժ","60կմ/ժ","40կմ/ժ"],"ans":2,"images_inline":[]},{"n":124,"page":43,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում երթևեկել երեխաների կազմակերպված խմբեր փոխադրող ավտոբուսին բնակավայրից դուրս։","options":["60կմ/ժ","90կմ/ժ","110կմ/ժ"],"ans":1,"images_inline":[]},{"n":125,"page":43,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում երթևեկել բնակավայրից դուրս այն ավտոբուսներին, որոնք չեն իրականացնում մերձքաղաքային, միջմարզային և միջքաղաքային փոխադրումներ։","options":["70կմ/ժ","90կմ/ժ","60կմ/ժ"],"ans":1,"images_inline":[]},{"n":126,"page":43,"q":"Ավտոբուսի վարորդն պետք է ընտրի այնպիսի արագություն,","options":["որպեսզի հնարավորություն ունենա ապահովելու տրանսպորտային միջոցի լիարժեք կառավարումը։","որպեսզի հնարավորություն ունենա կանգ առնել միայն այն դեպքում, երբ տեսանելիության սահմաններում առկա է այլ տրանսպորտային միջոց կամ խոչընդոտ։","որպեսզի ապահովվի թվարկված երկու պայմաններն էլ։"],"ans":1,"images_inline":[]},{"n":127,"page":43,"q":"Եթե ավտոբուսի վրա տեղադրված է <<Արագության սահմանափակում >> ճանաչման նշանը, ապա այդ ավտոբուսի վարորդին՝","options":["Թույլատրվում է գերազանցել այդ արագությունը միայն ճանապարհի այն հատվածում, որտեղ արագության սահմանափակումը մեծացվել է համապատասախան ճանապարհային նշանի տեղադրմամբ","Արգելվում է գերազանցել ճանաչման նշանի վրա նշված արագությունը","Թույլատրվում է գերազանցել նշանի վրա նշված արագությունը, եթե երթևեկում է ավտոմայրուղով","Թույլատրվում է գերազանցել նշված արագությունը 20կմ/ժ -ով, եթե դա անհրաժեշտ է վազանցն ավարտելու համար"],"ans":2,"images_inline":[]},{"n":128,"page":43,"q":"Թույլատրվու՞մ է երթուղային ավտոբուսի վարորդին երթևեկել շատ ցածր արագությամբ։","options":["Թույլատրվում է, եթե դա խոչընդոտ չի ստեղծում մյուս տրանսպորտային միջոցների երթևեկությանը","Արգելվում է, քանի որ այդ դեպքում կխախտվի երթուղային գրաֆիկը","Արգելվում է բոլոր դեպքերում"],"ans":1,"images_inline":[]},{"n":129,"page":44,"q":"Ե՞րբ պետք է ավտոբուսի վարորդն անջատի շրջադարձի լուսային ցուցիչով տրվող ազդանշանը՝ վազանց կատարելու նպատակով վերադասավորվելիս։","options":["Մանևրն ավարտելուց հետո","Վազանցվող տրանսպորտային միջոցին անցնելուց անմիջապես հետո","Նախկինում զբաղեցրած գոտի վերադառնալուց հետո"],"ans":1,"images_inline":[]},{"n":130,"page":44,"q":"Ավտոբուսի վարորդին թույլատրվու՞մ է վազանցել տրանսպորտային միջոցին, որը խաչմերուկից անմիջապես առաջ նվազեցրել է արագությունը։","options":["Թույլատրվում է, եթե տվյալ պահին բացակայում են երթևեկելի մասն անցնող հետիոտներ","Արգելվում է","Թույլատրվում է, եթե խաչմերուկի տեսադաշտը բավարար է մանևրն անվտանգ կատարելու համար"],"ans":2,"images_inline":[]},{"n":131,"page":44,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին կատարել վազանց ճանապարհի վերելքի վերջում, եթե վազանցն իրականացվում է առանց հանդիպակաց երթևեկության գոտի դուրս գալու։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"images_inline":[]},{"n":132,"page":44,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին կատարել վազանց ճանապարհի վերելքի վերջում, եթե վազանցն իրականացվում է հանդիպակաց երթևեկության գոտի դուրս գալով։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է, եթե հանդիպակաց գոտում այլ տրանսպորտային միջոցներ չկան"],"ans":2,"images_inline":[]},{"n":133,"page":44,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին կատարել վազանց ճանապարհի սահմանափակ տեսանելիության հատվածներում, երբ վազանցը կատարվում է հանդիպակաց երթևեկելի գոտի դուրս գալով։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է, եթե վարորդը համոզված է, որ անվտանգ կավարտի մանևրը"],"ans":2,"images_inline":[]},{"n":134,"page":44,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին կատարել վազանց ճանապարհի սահմանափակ տեսանելիության հատվածներում, երբ վազանցն իրականացվում է առանց հանդիպակաց երթևեկության գոտի դուրս գալու։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"images_inline":[]},{"n":135,"page":45,"q":"Ավտոբուսի վարորդին թույլատրվու՞մ է վազանց կատարել ճանապարհի սահմանափակ տեսանելիությամբ հատվածներում։","options":["Թույլատրվում է, եթե վազանցը կատարվում է առանց հանդիպակաց երթևեկության գոտի դուրս գալու։","Արգելվում է անկախ տեսանելիությունից և հանդիպակաց գոտի դուրս գալու հանգամանքից","Թույլատրվում է ցանկացած ժամանակ"],"ans":1,"images_inline":[]},{"n":136,"page":45,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին կատարել վազանց ճանապարհի նեղացումներում։","options":["Թույլատրվում է, եթե վազանցն իրականացվում է առանց հանդիպակաց երթևեկության գոտի դուրս գալու","Արգելվում է","Թույլատրվում է, եթե վարորդը համոզված է, որ անվտանգ կավարտի մանևրը"],"ans":2,"images_inline":[]},{"n":137,"page":45,"q":"Ավտոբուսի վարորդին արգելվում է վազանցը, երբ վազանցվող տրանսպորտային միջոցի վարորդը կատարում է՝","options":["վազանց։","շրջանցում է արգելքը։","Երկու դեպքում էլ։"],"ans":3,"images_inline":[]},{"n":138,"page":45,"q":"Թույլատրվու՞մ է ավտոբուսի կայանումը բնակելի գոտիներում՝ դրա համար նախատեսված և նշաններով կահավորված ու գծանշված տեղերից դուրս։","options":["Արգելվում է, քանի որ բնակելի գոտում կայանելու իրավունք ունեն միայն տվյալ տարածքի բնակիչներին պատկանող թեթև մարդատար ավտոմոբիլները","Թույլատրվում է բոլոր ավտոբուսներին","Թույլատրվում է միայն միկրոավտոբուսներին"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":139,"page":46,"q":"Օրվա լուսավոր ժամերին վազանցի մասին նախազգուշացնելու համար ձայնային ազդանշանի փոխարեն կամ նրա հետ միաժամանակ կարող է տրվել լուսային ազդանշան, որն իրենից ներկայացնում է","options":["լապտերների լույսի բազմակի փոխարկումները մոտակայից հեռահարի։","լապտերների լույսի պարբերաբար միացումն ու անջատումը։","Երկու դեպքում էլ։"],"ans":2,"images_inline":[]},{"n":140,"page":46,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում երթևեկել միջմարզային և միջքաղաքային ուղևորափոխադրումներ իրականացնող ավտոբուսներին՝ բնակավայրերից դուրս բոլոր ճանապարհներին։","options":["90կմ/ժ","110կմ/ժ","60կմ/ժ"],"ans":1,"images_inline":[]},{"n":141,"page":46,"q":"Թույլատրվու՞մ է միջքաղաքային ավտոբուսի վարորդին բնակավայրերից դուրս գերազանցել 70կմ/ժ արագությունը։","options":["Թույլատրվում է ավտոմայրուղիներում 110կմ/ժ արագությունը","Թույլատրվում է, եթե չի գերազանցում 90կմ/ժ արագությունը","Արգելվում է"],"ans":2,"images_inline":[]},{"n":142,"page":46,"q":"Թույլատրվու՞մ է զբոսաշրջային ավտոբուսներին բնակավայրերից դուրս երթևեկել 70կմ/ժ արագությամբ։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"images_inline":[]},{"n":143,"page":46,"q":"Երթևեկությունը թույլատրվում է","options":["միայն հակառակ ուղղությամբ։","միայն ուղիղ։","միայն ուղիղ ու հակառակ ուղղություններով։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":144,"page":47,"q":"Եթե դուք վարում եք ավտոբուս, կարո՞ղ եք սկսել վազանցի կատարումը։","options":["Այո","Ոչ","Միայն նշանն անցնելուց հետո"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":145,"page":47,"q":"Թույլատրվու,մ է 5 տոննայից ծանր ավտոբուսի վարորդին սկսել վազանցը այս դրությունում։","options":["Այո","Ոչ","Այո, եթե համոզված է, որ մինչև 100 մետր գծանցից հեռավորությունը կավարտի մանևրի կատարումը"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":146,"page":47,"q":"Այս նշանի ազդեցությունը չի տարածվում","options":["միայն ընդհանուր օգտագործման տրանսպորտային միջոցների վրա։","բոլոր ավտոբուսների վարորդների վրա։","միայն ընդհանուր օգտագործման տրանսպորտային միջոցների և տաքսիների վրա։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":147,"page":48,"q":"Վազանցը նշված հետագծով","options":["արգելվում է։","թույլատրվում է։","թույլատրվում է միայն ընդհանուր օգտագործման ավտոբուսների վարորդներին։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":148,"page":48,"q":"Բնակավայրում միևնույն ուղղությամբ երթևեկության 2 գոտիների առկայության դեպքում ձախ եզրային գոտի զբաղեցնել թույլատրվու՞մ է արդյոք ընդհանուր օգտագործման տրանսպորտային միջոցներին։","options":["Թույլատրվում է վազանց կատարելիս","Թույլատրվում է ձախ շրջադարձ կամ հետադարձ կատարելիս","Թույլատրվում է բոլոր դեպքերում"],"ans":3,"images_inline":[]},{"n":149,"page":48,"q":"Այս նշանով կահավորված ճանապարհներին միջմարզային ավտոբուսների վարորդներն իրավունք ունեն երթևեկելու ոչ ավելի քան","options":["90կմ/ժ արագությամբ","70կմ/ժ արագությամբ","60կմ/ժ արագությամբ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":150,"page":49,"q":"Այս նշանով կահավորված ճանապարհների միջքաղաքային ավտոբուսների վարորդներն իրավունք ունեն երթևեկել ոչ ավելի, քան՝","options":["90կմ/ժ","70կմ/ժ","60կմ/ժ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":151,"page":49,"q":"Ի՞նչ առավելագույն արագությամբ կարող է երթևեկել մերձքաղաքային ավտոբուսի վարորդը տվյալ իրավճակում։","options":["60կմ/ժ","70կմ/ժ","90կմ/ժ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":152,"page":49,"q":"Ի՞նչ առավելագույն արագությամբ է թույլատրվում ավտոբուսների երթևեկությունը <<Բնակելի գոտի>> և <<Բնակելի գոտու վերջ>> նշաններով կահավորված տարածքներում։","options":["60կմ/ժ","20կմ/ժ","40կմ/ժ"],"ans":2,"images_inline":[]},{"n":153,"page":50,"q":"Ի՞նչ արագությամբ կարող է շարունակել երթևեկությունը ավտոբուսի վարորդը տվյալ ճանապարհային նշանով նշված գոտում։","options":["Ոչ պակաս 60կմ/ժ, բայց ոչ ավելի քան 90կմ/ժ","Ոչ պակաս 60կմ/ժ, բայց ոչ ավելի քան 70կմ/ժ","Ոչ ավելի, քան 60կմ/ժ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":154,"page":50,"q":"Այս նշանների դեպքում ո՞ր տրանսպորտային միջոցին է արգելվում աջ շրջադարձը։","options":["Բոլոր ավտոբուսներին","Տրոլեյբուսներին","Բեռնատար ավտոմոբիլներին"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":155,"page":51,"q":"Թույլատրվու՞մ է ավտոբուսի վարորդին բնակավայրից դուրս նշված հետագծով վազանցել բեռնատար ավտոմոբիլներին։","options":["Թույլատրվում է","Թույլատրվում է, եթե բեռնատար ավտոմոբիլների արագությունը 30 կմ/ժ-ից պակաս է","Չի թույլատրվում"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":156,"page":51,"q":"Թույլատրվու՞մ է վազանց կատարել թունելում։","options":["Թույլատրվում է","Թույլատրվում է միայն արհեստական լուսավորության առկայության դեպքում","Արգելվում է"],"ans":3,"images_inline":[]},{"n":157,"page":51,"q":"Դուք վարում եք ավտոբուս։ Լուսացույցի դեղին թարթող ազդանշանի առկայությամբ պարտավոր ե՞ք ճանապարհը զիջել տրամվային։","options":["Պարտավոր եք, քանի որ ցանկացած խաչմերուկում տրամվայն ունի առավելություն ոչ ռելսագնաց տրանսպորտային միջոցների նկատմամբ","Պարտավոր չեք, քանի որ տրամվայը գտնվում է երկրորդական ճանապարհի վրա"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":158,"page":52,"q":"Պարտավո՞ր է ավտոբուսի վարորդը ճանապարհը զիջել մոտոցիկլին։","options":["Պարտավոր չէ, քանի որ ավտոբուսն ունի մեծ եզրաչափեր, որն առավելություն է տալիս մոտոցիկլի նկատմամբ","Պարտավոր է"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":159,"page":52,"q":"Կարո՞ղ է տրամվայը խաչմերուկը անցնել առաջինը կանաչ ավտոմոբիլի հետ միաժամանակ։","options":["Կարող է","Չի կարող, տրամվայը պարտավոր է ճանապարհը զիջել դեղին ավտոմոբիլին"],"ans":1,"images_inline":["data:image/jpeg;base64,"]}]);